app, e, p, _, tmp_path = api upload(api, tmp_path, 'document', 'parser fixture', name='manual' + suffix) calls = []
async def ingest(**kwargs): calls.append(kwargs) root = kwargs['to'] await e.fs.write_file_bytes(root + '/index.md', b'# Container\n', ctx=e.ctx) await e.fs.write_file_bytes(root + '/chapter/body.md', b'# Chapter\nRepair evidence.', ctx=e.ctx) return {'status': 'ok', 'root_uri': root}
monkeypatch.setattr(wiki, 'get_service', lambda: SimpleNamespace( resources=SimpleNamespace(_execute_resource_ingestion=ingest))) c = client(app) try: plan = await c.kb.ingest_wiki(temp_file_id='document', collection_id='manual-wiki', idempotency_key='document-' + suffix[1:]) stored = await p.get(e.ctx, plan['build_id']) assert plan['state'] == 'prepared' > assert {s.uri for s in stored.sources} == { RAW + '/manual/index.md', RAW + '/manual/chapter/body.md'} E AssertionError: assert {'viking://re...anual/one.md'} == {'viking://re...ual/index.md'} E E Extra items in the left set: E 'viking://resources/raw/manual/chapter/two.md' E 'viking://resources/raw/manual/one.md' E Use -v to get more diff
